// Generated by tooling/unicode-cases/regexp.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: Greek omega and the Ohm sign have different legacy canonicalization classes.
const pattern0 = /^\u03a9$/i;
const pattern1 = /^\u03a9$/iu;
const pattern2 = /^\u03a9$/iv;
const samples: [string, boolean, boolean, boolean][] = [
  ["\u03a9", true, true, true],
  ["\u03c9", true, true, true],
  ["\u2126", false, true, true],
  ["\u03bf", false, false, false],
];
for (const sample of samples) {
  assert.sameValue(pattern0.test(sample[0]), sample[1], "ohm-canonicalization pattern 0");
  assert.sameValue(pattern1.test(sample[0]), sample[2], "ohm-canonicalization pattern 1");
  assert.sameValue(pattern2.test(sample[0]), sample[3], "ohm-canonicalization pattern 2");
}
